function luhn(nomor) {
  let total = 0, posisi = 0;
  for (let i = nomor.length - 1; i >= 0; i--) {
    if (nomor[i] === " ") continue;
    let d = Number(nomor[i]);
    if (posisi % 2 === 1) { d *= 2; if (d > 9) d -= 9; }
    total += d;
    posisi++;
  }
  return total % 10 === 0;
}
console.log("4111 1111 1111 1111:", luhn("4111 1111 1111 1111"), "| ...1112:", luhn("4111 1111 1111 1112"));

